        ["Drucken"] = "Print",
        ["DRUCKER"] = "PRINTER",
        ["Als PDF speichern"] = "Save as PDF",
        ["„Als PDF speichern“ erzeugt eine PDF-Datei mit exakt denselben Maßen wie der Ausdruck."] = "“Save as PDF” creates a PDF file with exactly the same dimensions as the printout.",
        ["Farbe"] = "Colour",
        ["Seiten"] = "Pages",
        ["Kopien"] = "Copies",
        ["PAPIER"] = "PAPER",
        ["Lage"] = "Orientation",
        ["Automatisch"] = "Automatic",
        ["Hochformat"] = "Portrait",
        ["Querformat"] = "Landscape",
        ["Automatisch: die Lage, bei der weniger Seiten nötig sind — bei Gleichstand bleiben Fotos aufrecht."] = "Automatic: the orientation that needs fewer pages — on a tie, photos stay upright.",
        ["Rand"] = "Margin",
        ["Abstand zur Blattkante. Die meisten Drucker können die äußeren 3–5 mm nicht bedrucken."] = "Distance to the edge of the sheet. Most printers cannot print the outer 3–5 mm.",
        ["Abstand"] = "Gap",
        ["Platz zwischen den Bildern zum Ausschneiden. Ab etwa 3 mm ist Raum für Schnittmarken."] = "Space between the images for cutting. From about 3 mm there is room for cut marks.",
        ["ANORDNUNG"] = "LAYOUT",
        ["Mehrere pro Seite — schneidefreundlich"] = "Several per page — easy to cut",
        ["Mehrere pro Seite — möglichst dicht"] = "Several per page — as dense as possible",
        ["Ein Bild pro Seite"] = "One image per page",
        ["Schneidefreundlich"] = "Easy to cut",
        ["Jede Seite lässt sich mit geraden Schnitten von Kante zu Kante zerlegen — ideal für die Schneidemaschine."] = "Every page can be cut apart with straight edge-to-edge cuts — ideal for a paper cutter.",
        ["Möglichst dicht"] = "As dense as possible",
        ["Spart Papier, aber nicht jede Schnittlinie geht durch das ganze Blatt."] = "Saves paper, but not every cutting line runs through the whole sheet.",
        ["Jedes Bild mittig auf einem eigenen Blatt."] = "Each image centred on its own sheet.",
        ["Bilder drehen, wenn es Platz spart"] = "Rotate images if it saves space",
        ["Ein Bild darf quer liegen, wenn dadurch weniger Seiten nötig sind. Bei Gleichstand bleiben Fotos aufrecht."] = "An image may be turned sideways if that needs fewer pages. On a tie, photos stay upright.",
        ["Zu große Bilder verkleinern"] = "Shrink images that are too large",
        ["Passt ein Bild nicht auf das Papier, wird es so weit verkleinert, dass es passt. Sonst wird es nicht gedruckt."] = "If an image doesn't fit on the paper, it is shrunk until it fits. Otherwise it is not printed.",
        ["Schnittmarken"] = "Cut marks",
        ["Feine Eckmarken im Abstand zwischen den Bildern — zeigen, wo geschnitten wird, ohne ins Bild zu ragen."] = "Fine corner marks in the gap between the images — they show where to cut without reaching into the image.",
        ["BILDER"] = "IMAGES",
        ["Sonst nur das Bild, das gerade angezeigt wird. Jedes Bild in der Größe aus seinen Einstellungen."] = "Otherwise only the image currently shown. Each image at the size from its settings.",
        ["Vorschau"] = "Preview",
        ["Vorherige Seite"] = "Previous page",
        ["Nächste Seite"] = "Next page",
        ["Foto 10 × 15 cm"] = "Photo 10 × 15 cm (4×6″)",
        ["Foto 13 × 18 cm"] = "Photo 13 × 18 cm (5×7″)",
        ["Einseitig"] = "One-sided",
        ["Doppelseitig — lange Kante"] = "Two-sided — long edge",
        ["Doppelseitig — kurze Kante"] = "Two-sided — short edge",
        ["Dieser Drucker druckt nur Schwarzweiß."] = "This printer only prints in black and white.",
        ["Schwarzweiß rechnet die Bilder selbst in Graustufen um (nach empfundener Helligkeit) — das wirkt auch im PDF und bei Druckern, die die Einstellung sonst übergehen."] = "Black and white converts the images to greyscale itself (by perceived brightness) — this also works in the PDF and on printers that otherwise ignore the setting.",
        ["Beim PDF entscheidet erst das Programm, mit dem es gedruckt wird."] = "For a PDF, the program it is printed from decides.",
        ["Dieser Drucker kann nicht beidseitig drucken."] = "This printer cannot print two-sided.",
        ["Lange Kante: geblättert wird wie in einem Buch.\nKurze Kante: geblättert wird nach oben, wie bei einem Kalender oder Klemmbrett."] = "Long edge: pages turn like in a book.\nShort edge: pages flip upwards, like a calendar or clipboard.",
        ["Alle geöffneten Bilder ({0})"] = "All open images ({0})",
        ["PDF speichern …"] = "Save PDF …",
        ["Dieser Drucker kann am Rand {0:0.#} mm nicht bedrucken — Bilder würden angeschnitten."] = "This printer cannot print the outer {0:0.#} mm — images would be cut off.",
        ["Bilder werden vorbereitet …"] = "Preparing images …",
        ["Nichts zu drucken"] = "Nothing to print",
        ["Seite {0} von {1}  ·  1 Bild"] = "Page {0} of {1}  ·  1 image",
        ["Seite {0} von {1}  ·  {2} Bilder"] = "Page {0} of {1}  ·  {2} images",
        ["„{0}“ ließ sich nicht lesen: {1}"] = "“{0}” could not be read: {1}",
        ["1 Bild ist größer als die bedruckbare Fläche — „Zu große Bilder verkleinern“ einschalten oder größeres Papier wählen."] = "1 image is larger than the printable area — turn on “Shrink images that are too large” or choose larger paper.",
        ["{0} Bilder sind größer als die bedruckbare Fläche — „Zu große Bilder verkleinern“ einschalten oder größeres Papier wählen."] = "{0} images are larger than the printable area — turn on “Shrink images that are too large” or choose larger paper.",
        ["Bilder werden für den Druck gerechnet …"] = "Rendering images for printing …",
