        ["PDF gespeichert: {0}  ·  {1} Seiten"] = "PDF saved: {0}  ·  {1} pages",
        ["An „{0}“ gesendet  ·  1 Seite"] = "Sent to “{0}”  ·  1 page",
        ["An „{0}“ gesendet  ·  {1} Seiten"] = "Sent to “{0}”  ·  {1} pages",
        ["{0} (Standard)"] = "{0} (default)",
        ["Drucken fehlgeschlagen: {0}"] = "Printing failed: {0}",
