        // ------------------------------------------------------------ AI
        ["KI-VERBESSERUNG"] = "AI ENHANCEMENT",
        ["Noch keine KI-Modelle vorhanden. Sie laufen komplett auf deinem Rechner und werden einmalig heruntergeladen."] = "No AI models yet. They run entirely on your computer and are downloaded once.",
        ["Modelle laden …"] = "Get models …",
        ["Modell"] = "Model",
        ["Stärke"] = "Strength",
        ["Deckkraft der KI-Bearbeitung über dem Original: 100 % = nur KI, 30 % = 70 % Original und 30 % KI. Wirkt sofort, ohne neu zu rechnen."] = "Opacity of the AI result over the original: 100 % = AI only, 30 % = 70 % original and 30 % AI. Works instantly, without recomputing.",
        ["Haut & Details"] = "Skin & details",
        ["Wirkt live auf das KI-Ergebnis, ohne neu zu rechnen."] = "Works live on the AI result, without recomputing.",
        ["Hautstruktur"] = "Skin texture",
        ["Nur Gesichtsmodelle: holt Poren und feine Hautstruktur aus dem Original zurück, damit Gesichter nicht glattgebügelt wirken. Augen, Mund und Form bleiben vom Modell. Wirkt live."] = "Face models only: brings pores and fine skin texture back from the original, so faces don't look ironed flat. Eyes, mouth and shape stay from the model. Works live.",
        ["Nur Gesichtsmodelle: holt Lachfalten, Stirn- und Mundlinien zurück, die das Modell geglättet hat — nur auf der Haut, Augen, Lippen und Zähne bleiben vom Modell. Wirkt live."] = "Face models only: brings back laugh lines, forehead and mouth lines that the model smoothed away — only on the skin; eyes, lips and teeth stay from the model. Works live.",
        ["Nur Gesichtsmodelle: Korn im Gesicht, damit es nicht sauberer wirkt als der Rest des Fotos — 100 % = aufgefüllt bis zum Korn des übrigen Bildes, je Helligkeit. Wirkt live."] = "Face models only: grain in the face, so it doesn't look cleaner than the rest of the photo — 100 % = filled up to the grain of the rest of the image, per brightness. Works live.",
        ["Nur Gesichtsmodelle: Größe des Korns — ×1 = wie im Foto gemessen, nach links feiner, nach rechts gröber. Wirkt live."] = "Face models only: size of the grain — ×1 = as measured in the photo, finer to the left, coarser to the right. Works live.",
        ["Nur Gesichtsmodelle, sobald ein Ergebnis da ist: zeigt, was wohin kommt — rot, wo Falten aus dem Original zurückkommen (je kräftiger, desto mehr), blau, was vom Modell bleibt (Augen, Brauen, Lippen, Zähne)."] = "Face models only, once there is a result: shows what goes where — red where wrinkles come back from the original (the stronger, the more), blue what stays from the model (eyes, brows, lips, teeth).",
        ["Nur CodeFormer: wie nah das Modell am Original bleibt — niedrig = stärkere Verbesserung, die Person kann sich aber verändern; hoch = näher am Original. Geht ins Modell — nach dem Verstellen rechnet „KI berechnen“ neu."] = "CodeFormer only: how close the model stays to the original — low = stronger improvement, but the person may change; high = closer to the original. Goes into the model — after changing it, “Compute AI” computes again.",
        ["Natürlichkeit geändert — „KI berechnen“ rechnet mit dem neuen Wert neu."] = "Naturalness changed — “Compute AI” computes again with the new value.",
        ["Falten"] = "Wrinkles",
        ["Körnung"] = "Grain",
        ["Korngröße"] = "Grain size",
        ["Karte zeigen"] = "Show map",
        ["Tipp: „Gesichtsbereiche“ in den Einstellungen laden — dann wirken Falten genauer."] = "Tip: download “Face regions” in the settings — wrinkles then work more precisely.",
        ["Gesichtsbereiche"] = "Face regions",
        ["Erkennt Haut, Augen, Mund … für die Detailregler"] = "Detects skin, eyes, mouth … for the detail sliders",
        ["BiSeNet (Face Parsing): teilt jedes Gesicht in Bereiche — Haut, Nase, Augen, Brauen, Lippen, Zähne, Haare. Damit kommen Falten und Korn nur auf die Haut, Augen und Zähne bleiben vom Modell. Wird mit jedem Gesichtsmodell automatisch geladen."] = "BiSeNet (face parsing): divides each face into regions — skin, nose, eyes, brows, lips, teeth, hair. Wrinkles then go only onto the skin; eyes and teeth stay from the model. Downloaded automatically with every face model.",
        ["zllrunning (face-parsing.PyTorch, BiSeNet), ONNX von FaceFusion"] = "zllrunning (face-parsing.PyTorch, BiSeNet), ONNX by FaceFusion",
        ["Natürlichkeit"] = "Fidelity",
        ["KI berechnen"] = "Compute AI",
        ["Rechnet das Modell und schreibt das Ergebnis ins Bild. Stärke, Haut, Falten und Körnung wirken danach weiter. Gerechnet wird immer auf dem Stand vor der letzten KI — nichts häuft sich an."] = "Runs the model and writes the result into the image. Strength, skin, folds and grain keep working on it afterwards. It always starts from the state before the last AI — nothing accumulates.",
        ["Fertig nach {0} — im Bild. Stärke, Haut, Falten und Körnung wirken weiter; rückgängig mit Strg+Z."] = "Done after {0} — in the image. Strength, skin, folds and grain keep working; undo with Ctrl+Z.",
        ["Im Bild — Stärke, Haut, Falten und Körnung wirken weiter; rückgängig mit Strg+Z."] = "In the image — strength, skin, folds and grain keep working; undo with Ctrl+Z.",
        ["Reihenfolge"] = "Order",
        ["Erst KI, dann Einstellungen"] = "AI first, then settings",
        ["Erst Einstellungen, dann KI"] = "Settings first, then AI",
        ["Einstellungen = Dunst, Licht, Farbe, Entrauschen und Schärfe. Sie wirken nie doppelt: entweder danach auf das KI-Ergebnis oder vorher ins Bild gerechnet."] = "Settings = haze, light, colour, noise reduction and sharpening. They never apply twice: either afterwards on the AI result, or baked into the image beforehand.",
        ["Die KI bekommt das fertig eingestellte Bild, Gesichter kommen zuletzt. Danach stehen die Regler auf null."] = "The AI gets the finished, adjusted image; faces come last. Afterwards the sliders are back at zero.",
        ["Die Einstellungen wirken danach auch auf die Gesichter und bleiben verstellbar."] = "The settings then also apply to the faces and stay adjustable.",
        ["„Erst Einstellungen“ geht nur bei Einstellungen je Bild — dazu „Gleiche Einstellungen für alle Bilder“ ausschalten."] = "“Settings first” only works with per-image settings — turn off “Same settings for all images”.",
        ["Einstellungen werden ins Bild gerechnet …"] = "Applying the settings to the image …",
        ["Läuft lokal auf deinem Rechner. Kann je nach Bild einige Minuten dauern."] = "Runs locally on your computer. Depending on the image it can take a few minutes.",
        ["Lizenz: nur für nicht-kommerzielle Nutzung."] = "License: non-commercial use only.",
        ["Modell fehlt — bitte in den Einstellungen herunterladen."] = "Model missing — please download it in the settings.",
        ["Zu groß: das Ergebnis hätte {0:0} Megapixel (höchstens {1})."] = "Too large: the result would have {0:0} megapixels (at most {1}).",
        ["Modell wird geladen …"] = "Loading model …",
        ["KI · {0}"] = "AI · {0}",
        ["Die Gesichtserkennung fehlt — bitte in den Einstellungen herunterladen."] = "Face detection is missing — please download it in the settings.",
        ["Kein Gesicht gefunden."] = "No face found.",
        ["1 Gesicht gefunden …"] = "1 face found …",
        ["{0} Gesichter gefunden …"] = "{0} faces found …",
        ["Wird übernommen …"] = "Applying …",
        ["Das Bild wurde inzwischen geändert — bitte neu berechnen."] = "The image has changed in the meantime — please compute again.",
        ["Die Regler wurden nach dem Berechnen verändert — bitte neu berechnen, damit das Ergebnis zu ihnen passt."] = "The sliders were changed after computing — please compute again so that the result matches them.",
        ["Treue, Details oder Gamma geändert: Bei über 4× wirkt das jetzt nur auf den zweiten Durchgang. Für das volle Ergebnis neu berechnen (≈ {0})."] = "Fidelity, details or gamma changed: above 4× this now only affects the second pass. Compute again for the full result (≈ {0}).",
        ["Das Bild wurde inzwischen gewechselt oder geändert – bitte noch einmal anwenden."] = "The image was switched or changed in the meantime – please apply again.",
        ["Neu berechnen rechnet vom Bild vor der KI – nicht KI auf KI."] = "Computing again starts from the image before the AI – not AI on AI.",
        ["Helle Darstellung"] = "Light appearance",
        ["Dunkle Darstellung (angenehm für die Augen)"] = "Dark appearance (easy on the eyes)",
        ["Darstellung"] = "Appearance",
        ["Wie das System"] = "As the system",
        ["Hell"] = "Light",
        ["Dunkel"] = "Dark",
        ["Dunkel ist ein gedämpftes, neutrales Grau statt Schwarz – angenehm für die Augen und ohne Farbstich, damit Fotos richtig wirken. Umschalten geht auch mit dem Knopf ☾/☀ oben rechts."] = "Dark is a muted, neutral grey instead of black – easy on the eyes and without a colour cast, so that photos look right. You can also switch with the ☾/☀ button at the top right.",
        ["Diese Ebene fortsetzen: Farbe, Stärke und Härte springen auf ihre Werte, neue Striche kommen dazu."] = "Continue this layer: colour, strength and hardness jump to its values, new strokes are added to it.",
        ["Diese Ebene mit allen ihren Strichen löschen."] = "Delete this layer with all its strokes.",
        ["Neue Ebene"] = "New layer",
        ["Eine neue Pinsel-Ebene mit den aktuellen Werten beginnen. Ebenen addieren sich: zwei grüne mit 30 % ergeben 60 %."] = "Start a new brush layer with the current values. Layers add up: two green ones at 30 % make 60 %.",
        ["Ebene {0}"] = "Layer {0}",
        ["1 Strich"] = "1 stroke",
        ["{0} Striche"] = "{0} strokes",
        ["Grün · {0:0} % · Härte {1:0} % · {2}"] = "Green · {0:0} % · hardness {1:0} % · {2}",
        ["Rot · Härte {0:0} % · {1}"] = "Red · hardness {0:0} % · {1}",
        ["Wie weich die Striche auslaufen: 100 % harte Kante; weniger läuft radial von der Mitte des Pinsels zum Rand aus, bei 0 % schon ab der Mitte. Der Pinsel-Kreis zeigt es. Gilt für die gewählte Ebene, auch für ihre schon gemalten Striche."] = "How softly the strokes fade out: 100 % a hard edge; less fades out radially from the middle of the brush to its edge, at 0 % starting right at the middle. The brush circle shows it. Applies to the selected layer, including its strokes already painted.",
        ["Wie viel von dem, was die grünen Striche überdecken, bleibt: 100 % ganz, 40 % zum Beispiel für ein Geländer – beim Unscharf-Modus zu 40 % scharf, beim Entfernen zu 40 % sichtbar. Gilt für die gewählte Ebene; mehrere Ebenen addieren sich."] = "How much of what the green strokes cover stays: 100 % all of it, 40 % for example for a railing – 40 % sharp in the blur mode, 40 % visible when removing. Applies to the selected layer; several layers add up.",
        ["Ausgeschaltete Bildschritte wurden dafür aus dem Bild genommen – gerechnet wird auf dem gezeigten Bild (Strg+Z holt sie zurück)."] = "Switched-off image steps were taken out of the image for this – the step works on the image shown (Ctrl+Z brings them back).",
        ["Ausgeschaltete Bildschritte: die übrigen werden neu gerechnet …"] = "Switched-off image steps: computing the others again …",
        ["Neu rechnen fehlgeschlagen: {0}"] = "Computing again failed: {0}",
        ["Hintergrund-Schritt ohne Maske."] = "Background step without a mask.",
        ["Das Modell „{0}“ fehlt."] = "The model “{0}” is missing.",
        ["ohne Haut & Details"] = "without skin & details",
        ["ohne Entfernen"] = "without removal",
        ["ohne Hintergrund-Schritt"] = "without background step",
        ["Tipp: Entfernen am besten vor der KI-Verbesserung – sie sieht dann schon das fertige Bild."] = "Tip: remove things before the AI enhancement – it then already sees the finished picture.",
        ["Tipp: Den Hintergrund am besten zuerst – das Modell erkennt das Motiv am unbearbeiteten Foto am sichersten, und die Regler rechnen danach nur im sichtbaren Bereich."] = "Tip: remove the background first – the model finds the subject most reliably on the untouched photo, and the sliders then only compute the visible area.",
        ["Nach der KI kamen weitere Bildschritte ({0}). Neu berechnen rechnet vom Bild vor der KI, die späteren Schritte sind dann nicht enthalten (Strg+Z holt sie zurück)."] = "Further image steps came after the AI ({0}). Computing again starts from the image before the AI; the later steps are then not included (Ctrl+Z brings them back).",
        ["Das Bild wurde inzwischen gewechselt – KI begradigen bitte noch einmal starten."] = "The image was switched in the meantime – please start the AI straightening again.",
        ["Die Markierung passte nach Drehen, Spiegeln oder Zuschneiden nicht mehr und wurde entfernt."] = "The marking no longer fitted after rotating, flipping or cropping and was removed.",
        ["Abgebrochen."] = "Cancelled.",
        ["Fehlgeschlagen — siehe Meldung oben."] = "Failed — see the message above.",
        ["  ·  noch ca. {0}"] = "  ·  about {0} left",


        // Edits list
        ["BEARBEITUNGEN"] = "EDITS",
        ["Noch keine Bearbeitungen an diesem Bild."] = "No edits on this image yet.",
        ["Neu anwenden"] = "Apply selection",
        ["Lässt sich nicht ausschalten — nur mit Rückgängig zurücknehmen."] = "Can't be switched off — only taken back with Undo.",
        ["Vergrößert — lässt sich nicht ausschalten, nur mit Rückgängig zurücknehmen."] = "Upscaled — can't be switched off, only taken back with Undo.",
        ["Danach wurde das Bild festgeschrieben — nur mit Rückgängig zurückzunehmen."] = "The image was made permanent afterwards — only Undo can take this back.",
        ["Das Bild wurde geändert — offenes Ergebnis verworfen, bitte neu berechnen."] = "The image was changed — open result discarded, please compute again.",
        ["Ausgeschaltete Funktionen fehlen in „Nachher“ und im Export. Entzerren, Gerade richten, Zuschnitt und Drehen rechnen immer aus dem Original – jede Stufe lässt sich einzeln ausschalten."] = "Switched-off functions are missing from “After” and from the export. Straightening, levelling, cropping and rotating are always computed from the original – each step can be switched off on its own.",
        ["Bearbeitungen: alle Funktionen, die an diesem Bild wirken. Mit dem Auge eine Funktion aus „Nachher“ und dem Export ausschalten."] = "Edits: all functions that act on this image. Use the eye to switch a function off for “After” and the export.",
        ["Nur die eingeschalteten Funktionen festschreiben: ausgeschaltete Regler gehen auf null, eine ausgeschaltete KI oder Haut & Details kommen aus dem Bild. Rückgängig mit Strg+Z."] = "Make only the switched-on functions permanent: switched-off sliders go to zero, a switched-off AI or skin details are taken out of the image. Undo with Ctrl+Z.",
        ["KI rechnet — Fortschritt unten in der Vorschau."] = "AI is computing — progress at the bottom of the preview.",
        ["Gesichter werden gesucht …"] = "Looking for faces …",
        ["Auswahl angewendet"] = "Selection applied",
        ["ohne KI"] = "without AI",
        ["Zuschnitt"] = "Crop",
        ["Links gedreht"] = "Rotated left",
        ["Rechts gedreht"] = "Rotated right",
        ["Gespiegelt"] = "Flipped",
        ["links ↔ rechts"] = "left ↔ right",
        ["KI: {0}"] = "AI: {0}",
        ["Stärke {0:0} %"] = "Strength {0:0} %",
        ["Haut {0:0} %"] = "Skin {0:0} %",
        ["Falten {0:0} %"] = "Wrinkles {0:0} %",
        ["Korn {0:0} %"] = "Grain {0:0} %",
