        // AI models (settings)
        ["Modelle lassen sich auch von Hand hineinlegen (je Modell ein Unterordner) — die App erkennt sie automatisch."] = "Models can also be placed there by hand (one subfolder per model) — the app detects them automatically.",
        ["Herunterladen"] = "Download",
        ["Löschen"] = "Delete",
        ["Modell von der Festplatte entfernen. Es lässt sich jederzeit neu laden."] = "Remove the model from the disk. It can be downloaded again at any time.",
        ["{0}  ·  Lizenz {1}"] = "{0}  ·  License {1}",
        ["(nur nicht-kommerziell)"] = "(non-commercial only)",
        ["wird geladen …"] = "downloading …",
        ["✓ vorhanden"] = "✓ installed",
        ["nicht geladen"] = "not downloaded",
        ["Download fehlgeschlagen: {0}"] = "Download failed: {0}",
        ["Gerade läuft eine KI-Berechnung — danach löschen."] = "An AI calculation is running — delete afterwards.",
        ["Löschen fehlgeschlagen: {0}"] = "Delete failed: {0}",
        ["Die heruntergeladene Datei ist beschädigt oder wurde verändert (Prüfsumme stimmt nicht)."] = "The downloaded file is damaged or has been modified (checksum does not match).",
        ["Allround (klein)"] = "All-round (small)",
        ["Rauschen, JPEG-Artefakte, leichte Unschärfe"] = "Noise, JPEG artefacts, slight blur",
        ["Real-ESRGAN „general x4v3“: kleines, schnelles Modell für Fotos aus Handy und Netz. Entfernt Rauschen und Kompressionsblöcke und macht Kanten klarer. Kann vergrößern (bis 4×)."] = "Real-ESRGAN “general x4v3”: small, fast model for photos from phones and the web. Removes noise and compression blocks and makes edges clearer. Can upscale (up to 4×).",
        ["Xintao Wang (Real-ESRGAN), ONNX von Qualcomm AI Hub"] = "Xintao Wang (Real-ESRGAN), ONNX by Qualcomm AI Hub",
        ["Gesichtserkennung"] = "Face detection",
        ["Findet Gesichter für die Gesichtsmodelle"] = "Finds faces for the face models",
        ["YuNet (OpenCV): sehr kleines Modell, das Gesichter und Augen, Nase, Mund findet. Wird mit jedem Gesichtsmodell automatisch geladen."] = "YuNet (OpenCV): very small model that finds faces and eyes, nose, mouth. Downloaded automatically with every face model.",
        ["Shiqi Yu u. a. (OpenCV Zoo), ONNX von FaceFusion"] = "Shiqi Yu et al. (OpenCV Zoo), ONNX by FaceFusion",
        ["Gesichter – GFPGAN 1.4"] = "Faces – GFPGAN 1.4",
        ["Augen, Mund, Haut bei unscharfen Gesichtern"] = "Eyes, mouth, skin in blurry faces",
        ["GFPGAN 1.4: stellt unscharfe oder kleine Gesichter natürlich wieder her. Nur die Gesichter werden verändert, der Rest des Bildes bleibt, wie er ist."] = "GFPGAN 1.4: restores blurry or small faces naturally. Only the faces are changed, the rest of the image stays as it is.",
        ["TencentARC (GFPGAN), ONNX von FaceFusion"] = "TencentARC (GFPGAN), ONNX by FaceFusion",
        ["Gesichter – GFPGAN 1.3"] = "Faces – GFPGAN 1.3",
        ["Natürlicher, etwas weicher als 1.4"] = "More natural, a little softer than 1.4",
        ["GFPGAN 1.3: ältere Fassung von GFPGAN, laut den Entwicklern natürlicher und mit weniger künstlichen Details als 1.4. Nur die Gesichter werden verändert, der Rest des Bildes bleibt, wie er ist."] = "GFPGAN 1.3: older version of GFPGAN, according to its developers more natural and with fewer artificial details than 1.4. Only the faces are changed, the rest of the image stays as it is.",
        ["Gesichter – RestoreFormer++"] = "Faces – RestoreFormer++",
        ["Echte, unscharfe Fotos, hält die Person gut"] = "Real blurry photos, keeps the person recognisable",
        ["RestoreFormer++: neueres Modell für echte, unscharfe oder verrauschte Fotos. Bleibt meist nah an der Person und erfindet weniger Details. Nur die Gesichter werden verändert."] = "RestoreFormer++: newer model for real blurry or noisy photos. Usually stays close to the person and invents fewer details. Only the faces are changed.",
        ["Gesichter – CodeFormer"] = "Faces – CodeFormer",
        ["Stark beschädigte Gesichter, alte Fotos"] = "Badly damaged faces, old photos",
        ["CodeFormer: kommt auch mit sehr schlechten Gesichtern zurecht (alte Fotos, starke Kompression). Nur die Gesichter werden verändert. Lizenz erlaubt nur nicht-kommerzielle Nutzung."] = "CodeFormer: copes even with very poor faces (old photos, heavy compression). Only the faces are changed. The license allows non-commercial use only.",
        ["Shangchen Zhou (CodeFormer), ONNX von FaceFusion"] = "Shangchen Zhou (CodeFormer), ONNX by FaceFusion",
        ["Zhouxia Wang u. a. (RestoreFormer++), ONNX von FaceFusion"] = "Zhouxia Wang et al. (RestoreFormer++), ONNX by FaceFusion",

        // ------------------------------------------------------------ Settings, language
        ["Einstellungen"] = "Settings",
        ["Schließen"] = "Close",
        ["Laufende Downloads gehen im Hintergrund weiter."] = "Running downloads continue in the background.",
        ["Sprache"] = "Language",
        ["Weitere Sprachen: eine JSON-Datei in den Ordner „languages“ neben dem Programm legen. Die Vorlage enthält alle Texte mit englischer Übersetzung zum Übersetzen."] = "More languages: put a JSON file into the “languages” folder next to the program. The template contains every text with its English translation to translate from.",
        ["Vorlage erstellen"] = "Create template",
        ["Schreibt _vorlage.json in den Ordner languages. Kopieren, umbenennen (z. B. fr.json), Code, Name, Flagge und Texte übersetzen."] = "Writes _vorlage.json into the languages folder. Copy it, rename it (e.g. fr.json), then fill in code, name, flag and translate the texts.",
        ["Nicht geladene Sprachdateien:"] = "Language files not loaded:",
        ["Kein Dateimanager gefunden. Ordner: {0}"] = "No file manager found. Folder: {0}",
        ["Vorlage gespeichert: {0}"] = "Template saved: {0}",
        ["Vorlage ließ sich nicht speichern: {0}"] = "Could not save the template: {0}",
        ["Kein Schreibrecht im Ordner {0}"] = "No write permission in the folder {0}",
        ["{0}: Deutsch ist eingebaut und lässt sich nicht ersetzen."] = "{0}: German is built in and cannot be replaced.",
        ["kein JSON-Objekt"] = "not a JSON object",

        // Free rotation
        ["Frei drehen: mit dem Regler unten um einen beliebigen Winkel drehen, z. B. den Horizont gerade richten. Der Rahmen zeigt, was übrig bleibt – er passt sich beim Drehen an und lässt sich danach verschieben und verkleinern. „Drehen und zuschneiden“ übernimmt, Esc verwirft."] =
            "Rotate freely: turn the image by any angle with the slider below, e.g. to straighten the horizon. The frame shows what remains – it follows the angle and can then be moved and made smaller. “Rotate and crop” applies, Esc discards.",
        ["Drehen"] = "Rotate",
        ["Drehwinkel in Grad, positiv im Uhrzeigersinn. Pfeiltasten: 0,1°, Bild auf/ab: 1°."] = "Rotation angle in degrees, positive is clockwise. Arrow keys: 0.1°, Page up/down: 1°.",
        ["Drehung verwerfen (Esc)"] = "Discard rotation (Esc)",
        ["Drehen und zuschneiden"] = "Rotate and crop",
        ["Dreht das Bild und schneidet es auf den Rahmen zu – ein Schritt, Strg+Z macht ihn rückgängig. Auch mit Enter oder Doppelklick in den Rahmen."] =
            "Rotates the image and crops it to the frame – one step, Ctrl+Z undoes it. Also with Enter or a double-click inside the frame.",
        ["Gedreht"] = "Rotated",
        ["Gerade gerichtet"] = "Levelled",
        ["gespiegelt"] = "flipped",
        ["{0} × {1} px · runde Ecken"] = "{0} × {1} px · rounded corners",

        // Perspective correction
        ["Entzerren: die vier Ecken des Rahmens auf die Ecken von etwas legen, das in Wirklichkeit rechteckig ist – Blatt, Bild an der Wand, Fenster, Hausfront. Daraus wird ein gerades Rechteck, genau der Inhalt des Rahmens. Beim Ziehen hilft eine Lupe; Pfeiltasten verschieben die zuletzt gezogene Ecke um 1 px (Umschalt: 10 px)."] =
            "Straighten perspective: put the four corners of the frame on the corners of something that is really rectangular – a sheet, a picture on the wall, a window, a facade. It becomes a straight rectangle, exactly the content of the frame. A magnifier helps while dragging; arrow keys move the last dragged corner by 1 px (Shift: 10 px).",
        ["Entzerren"] = "Straighten",
        ["Die Ecken überkreuzen sich – bitte so legen, dass ein Viereck entsteht."] = "The corners cross – please place them so that they form a quadrilateral.",
        ["Ergebnis: {0} × {1} px"] = "Result: {0} × {1} px",
        ["Entzerren und zuschneiden"] = "Straighten and crop",
        ["Macht aus dem Rahmen ein gerades Rechteck – ein Schritt, Strg+Z macht ihn rückgängig. Auch mit Enter oder Doppelklick in den Rahmen; Esc bricht ab."] =
            "Turns the frame into a straight rectangle – one step, Ctrl+Z undoes it. Also with Enter or a double-click inside the frame; Esc cancels.",
        ["Entzerrt"] = "Straightened",

        // Standard formats
        ["DIN-Formate"] = "ISO A sizes",
        ["Fotoabzüge (cm)"] = "Photo prints (cm)",
        ["US-Formate"] = "US sizes",

        // White balance
        ["WEISSABGLEICH"] = "WHITE BALANCE",
        ["Weißabgleich"] = "White balance",
        ["Neutral"] = "Neutral",
        ["Schwarz"] = "Black",
        ["Weiß"] = "White",
        ["N"] = "N",
        ["S"] = "B",
        ["W"] = "W",
        ["Neutral: etwas anklicken, das in Wirklichkeit farblos ist (grau oder weiß ohne Farbton) – egal ob hell oder dunkel, z. B. Asphalt, Beton, eine graue Wolke, weißes Papier im Schatten. Nicht: grelles Weiß, fast Schwarzes, Beige oder Holz. Entfernt den Farbstich, die Helligkeit bleibt."] =
            "Neutral: click something that is really colourless (grey or white without a tint) – light or dark does not matter, e.g. asphalt, concrete, a grey cloud, white paper in the shade. Not: glaring white, near black, beige or wood. Removes the colour cast, the brightness stays.",
        ["Schwarz: die dunkelste Stelle anklicken, die schwarz sein sollte. Korrigiert die Schatten und macht sie satt schwarz."] =
            "Black: click the darkest spot that should be black. Corrects the shadows and makes them deep black.",
        ["Weiß: die hellste Stelle anklicken, die weiß sein sollte, aber noch Zeichnung hat. Korrigiert die Lichter und macht sie rein weiß."] =
            "White: click the brightest spot that should be white but still has detail. Corrects the highlights and makes them pure white.",
        ["Messungen dieser Pipette löschen (z. B. nach einem Fehlklick). Strg+Z nimmt nur den letzten Klick zurück."] =
            "Delete this eyedropper's measurements (e.g. after a wrong click). Ctrl+Z only undoes the last click.",
        ["Alle drei Pipetten zurücksetzen – der Weißabgleich ist dann aus."] = "Reset all three eyedroppers – white balance is then off.",
        ["Diese Stelle ist ausgefressen (reines Weiß, keine Farbe mehr) – bitte eine etwas dunklere Stelle wählen."] =
            "This spot is blown out (pure white, no colour left) – please choose a slightly darker spot.",
        ["Neutral: auf etwas klicken, das in Wirklichkeit farblos ist – egal ob hell oder dunkel, z. B. Asphalt, Beton, eine graue Wolke, weißes Papier im Schatten. Nicht: grelles Weiß, fast Schwarzes, Beige oder Holz. Mehrere Klicks werden gemittelt; Esc beendet."] =
            "Neutral: click something that is really colourless – light or dark does not matter, e.g. asphalt, concrete, a grey cloud, white paper in the shade. Not: glaring white, near black, beige or wood. Several clicks are averaged; Esc ends.",
        ["Schwarz: auf die dunkelste Stelle klicken, die schwarz sein sollte. Mehrere Klicks werden gemittelt; Esc beendet."] =
            "Black: click the darkest spot that should be black. Several clicks are averaged; Esc ends.",
        ["Weiß: auf die hellste Stelle klicken, die weiß sein sollte, aber noch Zeichnung hat (nicht ausgefressen). Mehrere Klicks werden gemittelt; Esc beendet."] =
            "White: click the brightest spot that should be white but still has detail (not blown out). Several clicks are averaged; Esc ends.",
        ["Pipette wählen und ins Bild klicken. Eine Pipette reicht – Neutral (grau) ist meist die beste. Mit Schwarz und Weiß dazu und mit mehreren Klicks wird es genauer."] =
            "Choose an eyedropper and click into the image. One is enough – Neutral (grey) is usually the best. Adding Black and White and clicking several times makes it more accurate.",
        // ------------------------------------------------------------ Graphics card (Settings › Performance)
        ["Diese Laufzeit kann keine Grafikkarte ansprechen — die KI rechnet auf der CPU."] = "This runtime cannot use a graphics card — the AI runs on the CPU.",
        ["Die Grafikkarte ({0}) ließ sich nicht nutzen — die KI rechnet auf der CPU. Grund: {1}"] = "The graphics card ({0}) could not be used — the AI runs on the CPU. Reason: {1}",
        ["Die KI-Scaler (Größe › Verfahren) rechnen auf der Grafikkarte ({0}), die übrigen Modelle (Gesichter, Entfernen, Begradigen) auf der CPU."] = "The AI scalers (Size › Method) run on the graphics card ({0}), the other models (faces, removal, straightening) on the CPU.",

        // ------------------------------------------------------------ Upscaling (group below "Size")
        ["Vielfaches des Bildes"] = "Multiple of the image",
        ["{0}×  ·  {1} × {2} px"] = "{0}×  ·  {1} × {2} px",
        ["Skalierung zurücksetzen: wieder die Größe des Bildes ({0} × {1} px)."] = "Reset scaling: back to the size of the image ({0} × {1} px).",
        ["Keine Größenänderung."] = "No change of size.",
        ["Keine Größenänderung — der KI-Scaler wirkt, sobald die Maße größer sind als das Bild (z. B. 4× im Menü der Formate)."] = "No change of size — the AI scaler takes effect as soon as the size is larger than the image (e.g. 4× in the formats menu).",
        ["Skalieren"] = "Scale",
        ["Skalieren (≈ {0})"] = "Scale (≈ {0})",
        ["Skalieren …"] = "Scaling …",
        ["Skalieren fehlgeschlagen: {0}"] = "Scaling failed: {0}",
        ["Die Vorschau zeigt das Ergebnis in voller Größe, nur skaliert — Licht, Farbe und Schärfe kommen zurück, sobald du etwas anderes einstellst."] = "The preview shows the result at full size, scaled only — light, colour and sharpening come back as soon as you change anything else.",
        ["Nur bei KI-Scalern. Treue-Sicherung: Das Ergebnis wird so nachgeführt, dass es verkleinert wieder genau das Original ergibt. Die KI darf Feines ergänzen, aber Formen, Helligkeit und Farben nicht verschieben. 100 % empfohlen."] = "AI scalers only. Fidelity guard: the result is corrected so that, scaled back down, it gives exactly the original again. The AI may add fine detail but must not shift shapes, brightness or colours. 100 % recommended.",
        ["Nur bei KI-Scalern. Wie viel von der KI kommt: 100 % = nur KI, weniger = gemischt mit dem einfach vergrößerten Bild (Lanczos). Wirkt sofort, ohne neu zu rechnen."] = "AI scalers only. How much comes from the AI: 100 % = AI only, less = mixed with the plainly enlarged image (Lanczos). Takes effect at once, without recomputing.",
        ["Pixel: Bildgröße in Pixeln. mm: Druckgröße in Millimetern — die Pixel ergeben sich aus der DPI. Die Einheit entscheidet auch, was eine neue DPI ändert: bei Pixel nur die Druckgröße, bei mm die Pixel."] = "Pixel: image size in pixels. mm: print size in millimetres — the pixels follow from the DPI. The unit also decides what a new DPI changes: with pixels only the print size, with mm the pixels.",
        ["Rechnet die Skalierung jetzt in voller Größe und zeigt sie in der Vorschau — zum Hineinzoomen und für Vorher/Nachher. Filter: Sekunden. KI: bei langer Dauer wird gefragt, ob der sichtbare Ausschnitt reicht; fertige Kacheln erscheinen sofort. Speichern geht auch ohne — bei KI wird dann gefragt."] = "Computes the scaling now at full size and shows it in the preview — for zooming in and for before/after. Filters: seconds. AI: if it takes long, you are asked whether the visible part is enough; finished tiles appear at once. Saving works without it too — with AI you are asked then.",
        ["Vielfaches des Bildes (2×, 4×, 16×) oder Standardformat wählen (A4, A5, Fotoabzüge …): Das Bild wird in Millimetern darauf gebracht – Hoch- oder Querformat wie das Bild, bei geschlossener Kette ganz hinein mit gleichem Seitenverhältnis. Die DPI bleibt (für den Druck 300 einstellen), die Pixel folgen."] = "Choose a multiple of the image (2×, 4×, 16×) or a standard format (A4, A5, photo prints …): the image is brought onto it in millimetres – portrait or landscape like the image, with the chain closed fully inside with the same aspect ratio. The DPI stays (set 300 for printing), the pixels follow.",
        ["Vergrößern mit KI – unter „Größe“, Liste „Verfahren“ (KI-Scaler). Real-ESRGAN x4v3 ist dieselbe Datei wie „Allround“ oben."] = "Enlarging with AI – under “Size”, list “Method” (AI scalers). Real-ESRGAN x4v3 is the same file as “Allround” above.",
        ["Womit die Pixel beim Skalieren entstehen. Die Liste richtet sich nach der Richtung: beim Verkleinern nur Filter, die dafür taugen; beim Vergrößern oben die Filter (sofort), unten die KI-Scaler (Sekunden bis Stunden). Gerechnet wird immer in einem Schritt aus dem Bild selbst."] = "How the pixels are made when scaling. The list follows the direction: when shrinking only filters suited to it; when enlarging the filters at the top (instant), the AI scalers below (seconds to hours). It is always computed in one step from the image itself.",
        ["{0}. Bei der Einheit Pixel ändert die DPI nur die Druckgröße — die Pixel bleiben. Bei mm bleibt die Druckgröße, die Pixel werden neu berechnet. Üblich: 72–96 Bildschirm · 150 einfacher Druck · 300 Fotodruck · 600 Kunstdruck · 1200 Strichzeichnungen; bis 2400 möglich."] = "{0}. With the unit pixels, the DPI only changes the print size — the pixels stay. With mm the print size stays and the pixels are recomputed. Usual: 72–96 screen · 150 simple print · 300 photo print · 600 fine-art print · 1200 line art; up to 2400 possible.",
        ["UPSCALING"] = "UPSCALING",
        ["Verfahren"] = "Method",
        ["Nur Filter"] = "Filter only",
        ["KI Real-ESRGAN x4v3 · schnell"] = "AI Real-ESRGAN x4v3 · fast",
        ["KI UltraSharpV2 · mittel"] = "AI UltraSharpV2 · medium",
        ["KI PiSA-SR · langsam"] = "AI PiSA-SR · slow",
        ["Wie bisher: der Filter oben rechnet die Pixel hoch. Sofort, erfindet nichts — wird aber weich."] = "As before: the filter above computes the extra pixels. Instant, invents nothing — but gets soft.",
        ["Real-ESRGAN x4v3: entfernt Rauschen und JPEG-Blöcke und macht Kanten klar. Sekunden je Bild, erfindet kaum etwas."] = "Real-ESRGAN x4v3: removes noise and JPEG blocks and makes edges crisp. Seconds per image, invents hardly anything.",
        ["Lädt das Modell in den Ordner „KI-Modelle“ neben dem Programm. Verwalten: Einstellungen › KI."] = "Downloads the model into the “KI-Modelle” folder next to the program. Manage: Settings › AI.",
        ["Herunterladen ({0})"] = "Download ({0})",
        ["Wird geladen … {0:0} % von {1}"] = "Downloading … {0:0} % of {1}",
        ["Treue"] = "Fidelity",
